<?php
require __DIR__.'/config.php';
require_admin();
mysqli_query($conn,"CREATE TABLE IF NOT EXISTS pesan_tamu (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,nama VARCHAR(100) NOT NULL,pesan TEXT NOT NULL,dibuat DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP)");
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$id=(int)($_POST['id']??0);if($id>0){$s=mysqli_prepare($conn,"DELETE FROM pesan_tamu WHERE id=?");mysqli_stmt_bind_param($s,'i',$id);mysqli_stmt_execute($s);mysqli_stmt_close($s);}header('Location:admin.php');exit;}
$result=mysqli_query($conn,"SELECT * FROM pesan_tamu ORDER BY id DESC");
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Admin</title></head><body><main><h1>⚙️ Admin Lab</h1><?php while($row=mysqli_fetch_assoc($result)):?><article><strong><?=h($row['nama'])?></strong><small> — <?=h($row['dibuat'])?></small><p><?=h($row['pesan'])?></p><form method="post"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['csrf_token'])?>"><input type="hidden" name="id" value="<?=h($row['id'])?>"><button>Hapus</button></form></article><hr><?php endwhile;?><a href="index.php">Beranda</a></main></body></html>